shell_commands:
mkdir /tmp/ajv-test && cd /tmp/ajv-test && npm init -y && npm i ajv@8 && cat << 'EOF' > test.mjs
import Ajv from 'ajv';
console.log(typeof Ajv);
EOF
node test.mjs

cat << 'EOF' > /tmp/ajv-test/test2.mjs
import Ajv from 'ajv';
const ajv = new Ajv({allErrors: true});
const validate = ajv.compile({
  type: 'object',
  properties: { location: { type: 'string' } },
  required: ['location']
});
validate({});
console.log(validate.errors);
validate({location: 123});
console.log(validate.errors);
EOF
node /tmp/ajv-test/test2.mjs

cat << 'EOF' > /tmp/ajv-test/test3.mjs
import Ajv from 'ajv';
const ajv = new Ajv({allErrors: true});
const validate = ajv.compile({
          type: 'object',
          properties: {ssn: {type: 'string'}},
          required: ['ssn'],
        });
validate({ssn: 123456789});
console.log(validate.errors);
EOF
node /tmp/ajv-test/test3.mjs

node -e "
import('./src/orchestration/tools/registry.js').then(({ ToolRegistry }) => {
  const registry = new ToolRegistry();
  registry.register({
    name: 'ssn_lookup',
    description: 'Look up record by identifier',
    inputSchema: {
      type: 'object',
      properties: {ssn: {type: 'string'}},
      required: ['ssn'],
    },
  }, async () => 'found');
  registry.execute('ssn_lookup', {ssn: 123456789}).then(res => console.log(res));
});
"
